"""
hybrid_render.py — Stem-hybrid renderer: realistic neural BED + symbolic DRUMS.

Architecture (see NEXT_STEPS_ROADMAP.md, Phase 2a):
    * BED  (bass + chords + melody) = realistic AUDIO, e.g. from MusicGen.
      In the study the bed is FROZEN, so it needs no parametric control.
    * DRUMS = generated by the symbolic groove engine, so the five groove
      knobs (density, syncopation, swing, microtiming, tempo) stay EXACT and
      measurable. This is the research instrument and must not be touched by
      any neural model.

The hard part is SYNCHRONIZATION. MusicGen does not emit an exact tempo or a
known downbeat, so we:
    1. detect the bed's tempo + downbeat from the audio (librosa),
    2. CONFORM the drum grid to the bed's detected tempo (re-render drums at
       that BPM) — far more robust than forcing MusicGen to a target BPM,
    3. ALIGN the drums so bar-1 beat-1 lands on the bed's first downbeat,
    4. MIX both audio stems to one file.

This module is GPU-free. The MusicGen step happens elsewhere (Colab GPU); here
we accept the bed as an audio file (real MusicGen clip, or a stand-in for
testing the alignment logic).
"""
from __future__ import annotations
import os
import numpy as np
import soundfile as sf
import librosa

from . import groovegen as gg


# --------------------------------------------------------------------------
# 0b. Bed percussion suppression (HPSS) — removes MusicGen's baked-in drums
# --------------------------------------------------------------------------
def _suppress_percussion(y: np.ndarray, sr: int, margin: float = 3.0,
                         makeup_db: float | None = None,
                         protect_melody: bool = True,
                         protect_hz: float = 2000.0,
                         protect_blend: float = 1.0) -> np.ndarray:
    """Return the HARMONIC component of `y`, dropping percussive transients.

    WHY THIS EXISTS
    ---------------
    MusicGen bakes its OWN drum kit into the bed even when the prompt says
    'no drums'. Those baked drums then fight the symbolic groove we align on
    top — two kick/snare/hat layers at slightly different phases = the
    'off-tempo / clashing' feel the user reported. Measured on the salsa bed:
    percussive/harmonic RMS ratio 0.51, ~6 strong percussive onsets/sec.

    librosa's harmonic/percussive source separation (HPSS) splits the
    spectrogram into a tonal (sustained pitches: piano, horns, bass, pads)
    component and a transient (drum hits) component. Keeping ONLY the harmonic
    part gives us a bed that carries the melody/harmony the user loves but no
    longer contains a competing drum layer, so OUR drums are the only groove.
    On the salsa bed this drops the perc/harm ratio 0.51 -> ~0.01.

    margin (>=1) controls separation aggressiveness. margin=3 is a good clean
    default; higher margins remove more percussion but soften the bed slightly.
    HPSS drops broadband energy, so `makeup_db` (default: auto RMS-match)
    restores the perceived loudness of the harmonic bed.

    MELODY-PROTECT (protect_melody, default True)
    ---------------------------------------------
    HPSS treats a melody's ATTACK TRANSIENTS and HIGH HARMONICS (Rhodes/pluck
    shimmer, vocal consonants, bright pick attacks) as 'percussive' and strips
    them. Measured on the neo-soul bed the harmonic-only extract loses ~12 dB
    at 2.5-6 kHz and ~23 dB at 6-12 kHz, and the melody-band (300-4000 Hz)
    waveform correlation vs. the original bed falls to ~0.91 — audibly this is
    the 'melody sounds warped/dull/distorted vs. MusicGen' the user reported.

    Kick/snare energy lives almost entirely BELOW ~2 kHz, so we can keep the
    aggressive HPSS strip in the low/mid band (where the baked drums are) while
    blending the ORIGINAL high band (>protect_hz) back in (where the melody's
    clarity lives and there is little drum energy). This restores the melody's
    shimmer/attacks — corr recovers to ~0.94 — while the perc/harm ratio stays
    low (~0.17 vs. 0.61 unprocessed). protect_blend in [0,1] scales how much of
    the original high band is restored (1.0 = full original highs).
    """
    y = np.asarray(y, dtype=np.float32)
    rms_before = float(np.sqrt(np.mean(y ** 2)) + 1e-12)
    try:
        y_harm = librosa.effects.harmonic(y, margin=float(margin)).astype(np.float32)
    except Exception:
        return y  # fail open: never break the pipeline over a filter
    if makeup_db is None:
        rms_after = float(np.sqrt(np.mean(y_harm ** 2)) + 1e-12)
        gain = rms_before / rms_after
        gain = float(np.clip(gain, 1.0, 4.0))  # only boost, cap at +12 dB
    else:
        gain = 10 ** (float(makeup_db) / 20.0)
    y_harm = (y_harm * gain).astype(np.float32)

    # MELODY-PROTECT: restore the original high band above protect_hz, where the
    # melody's transients/shimmer live and drum energy is negligible.
    if protect_melody and protect_hz and protect_blend > 0:
        try:
            from scipy.signal import butter, sosfiltfilt
            n = min(len(y), len(y_harm))
            y_in, y_h = y[:n], y_harm[:n]
            hp = butter(4, float(protect_hz), btype="high", fs=sr, output="sos")
            lp = butter(4, float(protect_hz), btype="low", fs=sr, output="sos")
            harm_lo = sosfiltfilt(lp, y_h).astype(np.float32)
            harm_hi = sosfiltfilt(hp, y_h).astype(np.float32)
            orig_hi = sosfiltfilt(hp, y_in).astype(np.float32)
            b = float(np.clip(protect_blend, 0.0, 1.0))
            y_harm = (harm_lo + (1.0 - b) * harm_hi + b * orig_hi).astype(np.float32)
        except Exception:
            pass  # fail open: keep the plain harmonic extract
    return y_harm.astype(np.float32)


# --------------------------------------------------------------------------
# 0. Beat backend: madmom (preferred) -> librosa (fallback)
# --------------------------------------------------------------------------
def _madmom_beat_grid(bed_wav: str, tempo_min: float, tempo_max: float):
    """Return (beat_times, downbeat_s, downbeats) using madmom's RNN activation.

    madmom's neural beat-activation function is far more reliable than librosa's
    autocorrelation tracker, especially on sustained/pad-heavy beds. The DBN
    post-processor in madmom 0.16.1 is broken under numpy>=1.24, so we run only
    the RNN and peak-pick the activation ourselves.

    CRITICAL: we return the ACTUAL detected beat positions, NOT a regularized
    metronomic grid. A neural bed (MusicGen) wanders in tempo within the clip;
    the warp downstream must follow that wander beat-by-beat, so the real beat
    times are exactly what it needs. (An earlier version returned a perfectly
    even grid, which is why the warp locked on steady synthetic beds but still
    drifted on real MusicGen beds.)

    We still octave-correct: if the detected beats are at half-time we INSERT
    real midpoints; if double-time we DECIMATE — both preserve local tempo
    variation instead of flattening it.

    We ALSO return the full sequence of detected DOWNBEATS. Empirically these are
    far more accurate than individual beat peaks (the downbeat activation channel
    is sharp on the bar boundary), so the warp uses them as primary anchors and
    only subdivides between them for intra-bar beats.
    Returns (None, None, None) if unavailable.
    """
    try:
        # compat shims for madmom 0.16.1 on modern Python/numpy
        import collections, collections.abc
        for _n in ("MutableSequence", "MutableMapping", "Mapping", "Sequence",
                   "Iterable", "Callable", "MutableSet"):
            if not hasattr(collections, _n):
                setattr(collections, _n, getattr(collections.abc, _n))
        for _a, _r in (("float", float), ("int", int), ("bool", bool),
                       ("object", object), ("complex", complex)):
            if not hasattr(np, _a):
                setattr(np, _a, _r)
        from madmom.features.downbeats import RNNDownBeatProcessor
        from scipy.signal import find_peaks
    except Exception:
        return None, None, None

    try:
        act = RNNDownBeatProcessor()(bed_wav)          # (frames, 2): P(beat),P(downbeat)
        fps = 100.0
        beat_strength = act[:, 0] + act[:, 1]
        downbeat_strength = act[:, 1]
        # peak-pick beats; min distance ~0.22s guards against double peaks
        peaks, _ = find_peaks(beat_strength, height=0.1, distance=int(0.22 * fps))
        if len(peaks) < 2:
            return None, None, None
        bt = peaks / fps                       # ACTUAL detected beat times (wander preserved)
        ibi = float(np.median(np.diff(bt)))
        sec_min, sec_max = 60.0 / tempo_max, 60.0 / tempo_min

        # Octave-correct by RESHAPING the real beat sequence, not replacing it:
        #  - half-time (beats too far apart): insert the real midpoint between
        #    each consecutive pair, so we get a denser grid that still follows
        #    the local tempo.
        #  - double-time (beats too close): keep every other beat.
        guard = 0
        while ibi > sec_max and guard < 4:
            mids = (bt[:-1] + bt[1:]) / 2.0
            bt = np.sort(np.concatenate([bt, mids]))
            ibi = float(np.median(np.diff(bt)))
            guard += 1
        guard = 0
        while ibi < sec_min and len(bt) > 3 and guard < 4:
            bt = bt[::2]
            ibi = float(np.median(np.diff(bt)))
            guard += 1

        # downbeats: the full sequence of strong downbeat peaks. These are the
        # most reliable anchors (sharp bar-boundary activation), so we return
        # them all, not just the first.
        dpk, _ = find_peaks(downbeat_strength, height=0.1, distance=int(0.6 * fps))
        downbeats = dpk / fps if len(dpk) else np.array([bt[0]])
        downbeat_s = float(downbeats[0])
        return bt, downbeat_s, downbeats
    except Exception:
        return None, None, None


# --------------------------------------------------------------------------
# 1. Analyze the bed audio
# --------------------------------------------------------------------------
def _fix_octave(tempo_bpm: float, tempo_min: float = 70.0,
                tempo_max: float = 180.0) -> float:
    """Correct half-time / double-time beat-tracking octave errors.

    librosa.beat.beat_track frequently locks onto half- or double-time (e.g.
    reports 61.5 for a true ~123 BPM track). We fold the estimate into a
    musically sensible band by doubling/halving until it lands in range. If the
    raw value is already in range we keep it.
    """
    t = float(tempo_bpm)
    if t <= 0:
        return t
    while t < tempo_min:
        t *= 2.0
    while t > tempo_max:
        t /= 2.0
    return t


def _octave_snap_grid(beat_times: np.ndarray, expected_tempo: float):
    """Snap a beat grid to the expected tempo octave.

    Very sparse / slow beds (the calm case) are octave-ambiguous: madmom may
    track them at half-time (e.g. 47 BPM for a true 63) or double-time. The
    downbeat POSITIONS are still right, but the beat DENSITY is wrong, so the
    drums end up at half/double the bed's true pulse. When the caller knows the
    intended tempo, we compare the detected inter-beat interval against the
    expected one and:
      * if detected is ~2x too slow  -> insert a beat between every pair (densify)
      * if detected is ~2x too fast  -> drop every other beat (thin)
    A single octave-fold decision is made per call (see FIX note below for why
    that is enough for this codebase -- every genre tempo band in
    genre_styles.py sits within one octave of its neighbors, so a real error is
    never more than one fold away).

    FIX (CODE_AUDIT.md finding #4, drum-grid trust): the previous version made
    this decision INSIDE a 2-iteration loop that re-tested the SAME fixed
    1.33/0.75 thresholds against the ratio produced by its OWN previous fold.
    That is unstable: folding once from a ratio of 1.55 (e.g. madmom reads 199
    BPM for a true 128 latin bed) lands at ratio 1.29 -- inside the "leave
    alone" window -- so the loop stopped one octave short at 99.5 BPM instead
    of continuing toward 128. Worse, widening the threshold enough to catch
    1.29 makes the loop oscillate (it then treats the corrected value as newly
    out-of-range and folds back the OTHER way, forever alternating between the
    two octaves depending on iteration parity). The fix is to make the
    densify-vs-thin-vs-leave-alone decision ONCE, directly from the raw
    (pre-fold) ratio, with no re-entrant re-testing of the post-fold value:
    that reproduces the exact 1.33/0.75 semantics for the documented 47-vs-63
    case while also correctly folding the 199-vs-128 case (199/128=1.555, one
    densify step -> 99.5 BPM -- the closest a pure octave-fold can get, since
    199 and 128 are not exact octave multiples; the residual ~28 BPM gap is a
    genuine tempo error, not an octave error, and is what analyze_bed's
    lock_tempo parameter exists to pin outright when the caller is sure).
    """
    bt = np.asarray(beat_times, dtype=float)
    if expected_tempo is None or len(bt) < 2:
        return bt
    exp_ibi = 60.0 / float(expected_tempo)
    ibi = float(np.median(np.diff(bt)))
    if ibi <= 0:
        return bt
    ratio = ibi / exp_ibi
    # thresholds at the geometric midpoints toward the half/double octaves
    # (sqrt(2)=1.41 boundary tightened to 1.30/0.769) -- decided ONCE from the
    # raw ratio, so there is no post-fold re-test to strand or oscillate on.
    if ratio > 1.30:                     # detected too slow -> densify
        mids = (bt[:-1] + bt[1:]) / 2.0
        bt = np.sort(np.concatenate([bt, mids]))
    elif ratio < (1.0 / 1.30):           # detected too fast -> thin
        bt = bt[::2]
    return bt

def analyze_bed(bed_wav: str, sr_target: int = 44100,
                tempo_min: float = 70.0, tempo_max: float = 180.0,
                expected_tempo: float | None = None,
                lock_tempo: float | None = None,
                suppress_bed_drums: bool = False,
                suppress_margin: float = 3.0,
                protect_melody: bool = True,
                protect_hz: float = 2000.0,
                protect_blend: float = 1.0) -> dict:
    """Detect tempo, beat times, and the first downbeat of a bed audio file.

    Returns a dict with:
        sr           : sample rate the audio was loaded at
        y            : the mono audio samples
        duration_s   : length in seconds
        tempo_bpm    : octave-corrected tempo estimate (float)
        tempo_raw    : the uncorrected librosa estimate (for transparency)
        beat_times   : array of beat onset times (s)
        downbeat_s   : time of the first downbeat (s) — where drum bar 1 starts

    tempo_min/tempo_max define the band used to correct half/double-time octave
    errors. Defaults (70-180) suit most pop/hip-hop/rock; widen for very slow
    calming beds (e.g. tempo_min=40) or very fast genres.

    suppress_bed_drums: if True, run HPSS to strip MusicGen's baked-in drum
    layer from the bed BEFORE both beat tracking and mixing. This is the fix
    for the 'clashing / off-tempo drums' case: with the bed's own drums gone,
    the symbolic groove is the only rhythmic layer, and beat detection locks to
    the tonal pulse instead of two competing kick/snare patterns. See
    _suppress_percussion for details. suppress_margin tunes aggressiveness.
    """
    y, sr = librosa.load(bed_wav, sr=sr_target, mono=True)
    duration_s = len(y) / sr

    # --- Optional: strip the bed's baked-in drums (HPSS harmonic component) ---
    # Do this FIRST so both the beat grid AND the mixed bed use the drum-free
    # audio. We write the suppressed bed to a temp file because the madmom
    # backend reads from a path, not the array.
    beat_src = bed_wav
    _tmp_beat_src = None
    if suppress_bed_drums:
        y = _suppress_percussion(y, sr, margin=suppress_margin,
                                 protect_melody=protect_melody,
                                 protect_hz=protect_hz,
                                 protect_blend=protect_blend)
        try:
            import tempfile
            fd, _tmp_beat_src = tempfile.mkstemp(suffix="_harm.wav")
            os.close(fd)
            sf.write(_tmp_beat_src, y, sr)
            beat_src = _tmp_beat_src
        except Exception:
            beat_src = bed_wav  # fall back to original for beat tracking only

    # --- Preferred backend: madmom RNN beat activation (real beat positions) ---
    backend = "madmom"
    beat_times, downbeat_s, downbeats = _madmom_beat_grid(beat_src, tempo_min, tempo_max)

    if beat_times is None or len(beat_times) < 2:
        # --- Fallback: librosa autocorrelation tracker ---
        backend = "librosa"
        downbeats = None
        tempo, beat_frames = librosa.beat.beat_track(y=y, sr=sr, trim=False)
        tempo_raw = float(np.atleast_1d(tempo)[0])
        beat_times = librosa.frames_to_time(beat_frames, sr=sr)
        if len(beat_times) > 0:
            downbeat_s = float(beat_times[0])
        else:
            onset_env = librosa.onset.onset_strength(y=y, sr=sr)
            onset_frames = librosa.onset.onset_detect(onset_envelope=onset_env, sr=sr)
            downbeat_s = float(librosa.frames_to_time(onset_frames, sr=sr)[0]) if len(onset_frames) else 0.0
        tempo_bpm = _fix_octave(tempo_raw, tempo_min, tempo_max)
    else:
        # madmom: derive an aggregate tempo from the median beat spacing (used
        # for RENDERING the drums); the warp uses the per-beat positions.
        ibi = float(np.median(np.diff(beat_times)))
        tempo_raw = 60.0 / ibi if ibi > 0 else 0.0
        tempo_bpm = _fix_octave(tempo_raw, tempo_min, tempo_max)

    # If the caller knows the intended tempo, snap the beat grid (and the tempo)
    # to the correct octave. This fixes the sparse/slow calm-bed case where
    # madmom legitimately can't tell 63 from 47 (half-time) and the drums would
    # otherwise lock to the wrong pulse. Downbeat positions are unaffected.
    if expected_tempo is not None and beat_times is not None and len(beat_times) >= 2:
        beat_times = _octave_snap_grid(beat_times, expected_tempo)
        ibi2 = float(np.median(np.diff(beat_times)))
        if ibi2 > 0:
            tempo_bpm = 60.0 / ibi2

    # HARD TEMPO LOCK (for genres whose felt pulse is known but whose dense
    # tonal texture defeats beat tracking -- e.g. a salsa piano montuno makes
    # madmom report ~101 BPM for a bed that is really a firm 95 BPM clave.
    # A 7%% tempo error is too small for _octave_snap_grid to touch, yet it
    # slides the drums progressively off the bed's accents. When the caller is
    # confident of the tempo, we PIN tempo_bpm exactly and keep only the most
    # reliable madmom downbeat for PHASE. _build_bed_grid then lays a steady
    # grid at the true tempo anchored to the real first downbeat.
    if lock_tempo is not None and float(lock_tempo) > 0:
        tempo_bpm = float(lock_tempo)

    # clean up the temp harmonic file if we made one
    if _tmp_beat_src is not None:
        try:
            os.remove(_tmp_beat_src)
        except Exception:
            pass

    return dict(sr=sr, y=y, duration_s=duration_s, tempo_bpm=tempo_bpm,
                tempo_raw=tempo_raw, beat_times=np.asarray(beat_times),
                downbeat_s=downbeat_s,
                downbeats=(np.asarray(downbeats) if downbeats is not None else None),
                beat_backend=backend, bed_drums_suppressed=bool(suppress_bed_drums),
                tempo_locked=(float(lock_tempo) if lock_tempo else None))


# --------------------------------------------------------------------------
# Build a clean, downbeat-anchored beat grid for the warp
# --------------------------------------------------------------------------
def _build_bed_grid(beat_times: np.ndarray, downbeats: np.ndarray | None,
                    downbeat_s: float, sec_per_beat: float,
                    bed_dur: float, beats_per_bar: int = 4) -> np.ndarray:
    """Reconstruct a clean 1-beat-per-entry grid that follows the bed's tempo.

    Empirically madmom's DOWNBEAT activation is far more accurate than its
    individual beat peaks (downbeat error ~1-10 ms vs. beat-peak error that
    accumulates to 100 ms+ by the end of a clip). So we anchor on the detected
    downbeats and subdivide each bar into `beats_per_bar` evenly-spaced beats.
    Even subdivision within a bar is an excellent approximation because tempo
    wander is slow relative to a single bar; the bar boundaries carry the
    wander, and the downbeats nail those.

    If downbeats are unavailable (librosa fallback) we fall back to cleaning the
    raw beat sequence: drop beats closer than 55%% of the local median IBI
    (spurious transients) and insert beats into gaps larger than 175%% (missed
    beats).
    """
    # ---- Preferred path: downbeat-anchored subdivision --------------------
    if downbeats is not None and len(downbeats) >= 2:
        db = np.asarray(downbeats, dtype=float)
        db = db[db >= downbeat_s - 1e-3]
        if len(db) == 0 or abs(db[0] - downbeat_s) > sec_per_beat * 0.5:
            db = np.concatenate([[downbeat_s], db])
        db = np.unique(np.round(db, 4))

        # ---- REGULARIZE INTO A STEADY GRID (period from beats, phase from db) --
        # The earlier design trusted each detected downbeat as a hard anchor and
        # subdivided between consecutive ones -> a single spurious/missed downbeat
        # produced a too-short/too-long span and the drums lurched ('sudden
        # speed-up'). A naive global polyfit over the downbeats is ALSO unsafe:
        # one spurious half-bar downbeat (e.g. a final 1.27 s 'bar' among real
        # 2.53 s bars) corrupts the median bar length, mis-assigns integer bar
        # indices, and tilts the whole line -> the entire grid runs at the wrong
        # tempo (drums constantly drift against the bed).
        #
        # Fix: DECOUPLE period from phase.
        #   * PERIOD comes from madmom's per-beat inter-beat-interval, which is a
        #     dense, robust statistic (sec_per_beat passed in == 60/tempo_bpm).
        #     This is far more reliable than differencing 4-5 sparse downbeats.
        #   * PHASE (where bar 1 sits) comes from the downbeats, but ONLY after
        #     rejecting any downbeat whose spacing is inconsistent with the true
        #     bar length (period * beats_per_bar). We then least-squares fit just
        #     the intercept with the slope PINNED to the known bar period.
        # Result: a perfectly steady grid locked to the bed's real tempo, immune
        # to a single bad downbeat, and never lurching locally.
        bar_period = float(sec_per_beat * beats_per_bar)   # trusted period
        beat_period = float(sec_per_beat)

        # assign each downbeat an integer bar index using the TRUSTED bar period
        rel = (db - db[0]) / bar_period
        idx = np.round(rel).astype(int)
        # reject downbeats that don't sit on the trusted bar lattice (a spurious
        # half-bar downbeat lands near k+0.5 -> residual ~0.5 bar, rejected)
        resid = np.abs(rel - idx)
        good = resid < 0.30                      # within 30%% of a bar of a lattice point
        # de-duplicate: keep the first downbeat at each integer index
        seen, ux, ut = set(), [], []
        for k, t0, ok in zip(idx, db, good):
            if ok and k not in seen:
                seen.add(k); ux.append(k); ut.append(t0)
        ux = np.asarray(ux, dtype=float); ut = np.asarray(ut, dtype=float)
        # fit ONLY the phase: minimise sum((ut - (start + ux*bar_period))^2)
        # -> start = mean(ut - ux*bar_period).  Slope is pinned, so no outlier
        # can change the tempo; it can only nudge the phase slightly.
        if len(ux) >= 1:
            start = float(np.mean(ut - ux * bar_period))
        else:
            start = float(downbeat_s)

        # BACK-PROJECT the phase to the START of the audio. Some beds (sparse,
        # legato neo-soul) only yield reliable downbeats late in the clip -- e.g.
        # the only detected downbeats sit at 8.5 s in an 11 s bed. Anchoring the
        # grid at that late downbeat and discarding everything before it left the
        # first ~8 s with NO drums. Since the grid is a perfectly steady lattice
        # (phase fixed, period trusted), we can slide `start` backward by whole
        # BEATS until it sits just inside t=0, so the drums cover the whole bed
        # while keeping the exact same phase relationship to the real downbeat.
        if start > 0:
            start -= beat_period * np.ceil(start / beat_period)
        # `start` is now the first grid beat at or just before 0 (in [-beat,0]).

        # lay a perfectly regular beat grid covering the whole bed
        n_beats = int(np.ceil((bed_dur - start) / beat_period)) + beats_per_bar + 1
        grid = start + np.arange(max(n_beats, 2)) * beat_period
        # keep beats that fall inside the bed (drop the tiny negative lead-in)
        grid = grid[grid >= -1e-6]
        return np.asarray(grid, dtype=float)

    # ---- Fallback path: clean the raw beat sequence -----------------------
    bed_grid = np.asarray(beat_times, dtype=float)
    bed_grid = bed_grid[bed_grid >= downbeat_s - 1e-3]
    if len(bed_grid) == 0 or abs(bed_grid[0] - downbeat_s) > sec_per_beat * 0.25:
        bed_grid = np.concatenate([[downbeat_s], bed_grid])
    med_ibi = float(np.median(np.diff(bed_grid))) if len(bed_grid) >= 2 else sec_per_beat
    if med_ibi <= 0:
        med_ibi = sec_per_beat
    cleaned = [float(bed_grid[0])]
    for tt in bed_grid[1:]:
        gap = tt - cleaned[-1]
        if gap < 0.55 * med_ibi:
            continue
        while gap > 1.75 * med_ibi:
            cleaned.append(cleaned[-1] + med_ibi)
            gap = tt - cleaned[-1]
        cleaned.append(float(tt))
    return np.asarray(cleaned, dtype=float)


# --------------------------------------------------------------------------
# 1b. Cached bed analysis (Roadmap 4.2) — slow-loop / bed-bank prep step
# --------------------------------------------------------------------------
# Keyed by (abspath, mtime, <analyze kwargs that change the grid>). A live
# session calls get_bed_info() once per bed (or once per grid-affecting
# parameter change); every subsequent per-bar control-loop tick reuses the
# cached dict instead of re-running madmom + HPSS (analyze_bed is the
# expensive step: full audio load + librosa HPSS + madmom RNN inference).
_BED_INFO_CACHE: dict[tuple, dict] = {}


def _bed_cache_key(bed_wav: str,
                   expected_tempo: float | None,
                   lock_tempo: float | None,
                   suppress_bed_drums: bool,
                   tempo_min: float,
                   tempo_max: float) -> tuple:
    """Cache key: bed identity (path+mtime) + every analyze_bed kwarg that can
    change the resulting beat grid. Kwargs that do NOT affect the grid
    (suppress_margin, protect_melody, protect_hz, protect_blend affect the
    *audio* used for beat tracking/mixing but are tuning details of the same
    suppression path, not alternate grids callers are expected to A/B live)
    are intentionally excluded to avoid needless cache misses; if a caller
    changes those they should call get_bed_info(..., force=True).
    """
    abspath = os.path.abspath(bed_wav)
    try:
        mtime = os.path.getmtime(abspath)
    except OSError:
        mtime = None
    return (abspath, mtime, expected_tempo, lock_tempo,
            bool(suppress_bed_drums), float(tempo_min), float(tempo_max))


def get_bed_info(bed_wav: str,
                 expected_tempo: float | None = None,
                 lock_tempo: float | None = None,
                 tempo_min: float = 70.0,
                 tempo_max: float = 180.0,
                 suppress_bed_drums: bool = True,
                 force: bool = False,
                 **analyze_kwargs) -> dict:
    """Cached analyze_bed(): the slow-loop / bed-bank prep step (Roadmap 4.2).

    Runs analyze_bed() once per (bed file, grid-affecting kwargs) and caches
    the result keyed by (abspath, mtime, expected_tempo, lock_tempo,
    suppress_bed_drums, tempo_min, tempo_max) — mtime guards against a stale
    hit if the bed file on disk changes without the path changing. Repeat
    calls with the same key return the SAME cached dict object (not a copy),
    so callers must treat it as read-only except for the extra fields this
    function precomputes (below) and the "_src" bookkeeping key that
    render_aligned_drums/render_aligned_drum_bar set.

    suppress_bed_drums DEFAULTS TO TRUE (matching analyze_bed). The curated
    library beds are full MusicGen instrumentals whose prompts request drums
    ("tight steady drums", "softly swung drums", ...), so every bed carries a
    baked-in drum kit. The closed-loop/segment renderer then overlays its OWN
    controllable synthetic drum layer -- if the bed's baked drums are NOT
    stripped, the two kits play at slightly different phases and the mix sounds
    off-beat / incoherent (the exact 'drums sound off, not synchronized'
    report). Stripping via HPSS (see _suppress_percussion) leaves the bed's
    loved melody/harmony intact (high-band shimmer protected) while removing the
    competing drums, so the synthetic groove is the only rhythmic layer. Pass
    suppress_bed_drums=False ONLY for a bed you KNOW is already drumless.

    On a fresh (cache-miss) call this also precomputes and stores on the
    dict, so per-bar calls never rebuild them:
        bed_grid      : the downbeat-anchored beat grid array (_build_bed_grid)
        sec_per_beat  : 60 / tempo_bpm
        sec_per_bar   : 4 * sec_per_beat (4/4)
        _src          : bed_wav (used by render_aligned_drums as an out_wav
                        fallback directory hint, kept for compatibility)

    Any extra analyze_kwargs (suppress_margin, protect_melody, protect_hz,
    protect_blend) are forwarded to analyze_bed on a cache MISS only; they do
    not participate in the cache key (see _bed_cache_key), so if you need to
    A/B those live, pass force=True to bypass the cache for that call.
    """
    key = _bed_cache_key(bed_wav, expected_tempo, lock_tempo,
                         suppress_bed_drums, tempo_min, tempo_max)
    if not force and key in _BED_INFO_CACHE:
        return _BED_INFO_CACHE[key]

    bed_info = analyze_bed(
        bed_wav,
        tempo_min=tempo_min, tempo_max=tempo_max,
        expected_tempo=expected_tempo, lock_tempo=lock_tempo,
        suppress_bed_drums=suppress_bed_drums,
        **analyze_kwargs,
    )
    bed_info["_src"] = bed_wav

    # Precompute the beat grid + per-beat/per-bar timing ONCE so per-bar calls
    # (render_aligned_drum_bar) never rebuild it. Mirrors render_aligned_drums'
    # own grid construction so both paths see byte-identical grid math.
    tempo_bpm = bed_info["tempo_bpm"]
    sec_per_beat = 60.0 / tempo_bpm
    beat_times = bed_info.get("beat_times", None)
    downbeats = bed_info.get("downbeats", None)
    downbeat_s = bed_info["downbeat_s"]
    bed_dur = bed_info["duration_s"]

    if beat_times is not None and len(beat_times) >= 2:
        bed_grid = _build_bed_grid(
            np.asarray(beat_times, dtype=float),
            downbeats if downbeats is None else np.asarray(downbeats, dtype=float),
            downbeat_s, sec_per_beat, bed_dur)
    else:
        bed_grid = None

    bed_info["bed_grid"] = bed_grid
    bed_info["sec_per_beat"] = sec_per_beat
    bed_info["sec_per_bar"] = sec_per_beat * 4.0

    _BED_INFO_CACHE[key] = bed_info
    return bed_info


# --------------------------------------------------------------------------
# Shared symbolic time-map (Roadmap 4.1): drum clock -> bed clock
# --------------------------------------------------------------------------
def _make_map_time(bed_info: dict):
    """Build the map_time(t_drum) -> bed_time closure shared by the batch
    renderer (render_aligned_drums) and the per-bar renderer
    (render_aligned_drum_bar), so the alignment math cannot diverge between
    the two paths.

    Uses bed_info['bed_grid'] if already precomputed (get_bed_info always
    does this); otherwise builds it on the fly from beat_times/downbeats
    (keeps render_aligned_drums working unchanged if it is ever called with a
    bare analyze_bed() dict that skipped get_bed_info()).

    Returns (map_time, sec_per_beat, bed_grid) — bed_grid is None if no beat
    grid is available at all (degenerate/empty beat_times), in which case
    map_time is None and the caller should fall back to _simple_align.
    """
    tempo_bpm = bed_info["tempo_bpm"]
    bed_dur = bed_info["duration_s"]
    downbeat_s = bed_info["downbeat_s"]
    sec_per_beat = bed_info.get("sec_per_beat") or (60.0 / tempo_bpm)

    bed_grid = bed_info.get("bed_grid", None)
    if bed_grid is None:
        beat_times = bed_info.get("beat_times", None)
        downbeats = bed_info.get("downbeats", None)
        if beat_times is not None and len(beat_times) >= 2:
            bed_grid = _build_bed_grid(
                np.asarray(beat_times, dtype=float),
                downbeats if downbeats is None else np.asarray(downbeats, dtype=float),
                downbeat_s, sec_per_beat, bed_dur)

    if bed_grid is None or len(bed_grid) < 2:
        return None, sec_per_beat, None

    bed_grid = np.asarray(bed_grid, dtype=float)
    beat_idx = np.arange(len(bed_grid), dtype=float)
    head_spb = (bed_grid[1] - bed_grid[0]) if len(bed_grid) >= 2 else sec_per_beat
    tail_spb = (bed_grid[-1] - bed_grid[-2]) if len(bed_grid) >= 2 else sec_per_beat

    def map_time(t_drum: float) -> float:
        bn = t_drum / sec_per_beat
        if bn <= beat_idx[-1] and bn >= 0:
            return float(np.interp(bn, beat_idx, bed_grid))
        if bn < 0:
            return float(bed_grid[0] + bn * head_spb)
        return float(bed_grid[-1] + (bn - beat_idx[-1]) * tail_spb)

    return map_time, sec_per_beat, bed_grid


# --------------------------------------------------------------------------
# 2 + 3. Render drums CONFORMED to the bed tempo, then ALIGN to its downbeat
# --------------------------------------------------------------------------
def render_aligned_drums(
    bed_info: dict,
    drum_style: str,
    *,
    event_density: int = 10,
    syncopation_level: float = 0.3,
    swing_amount: float = 1.0,
    microtiming_variance_ms: float = 0.0,
    seed: int = 0,
    sf2_path: str | None = None,
    out_wav: str | None = None,
) -> dict:
    """Render a symbolic drum stem at the BED's tempo and aligned to its downbeat.

    The groove knobs are passed straight through to GrooveParams, so the drum
    manipulation is identical to the study path — only the *tempo* is taken from
    the bed instead of being fixed, which is what locks the two stems together.

    DESIGN NOTE (Roadmap 2.5 — do NOT undo this): this function builds ONE bar
    via PatternBuilder.build_core() and TILES it bit-identically across the
    whole clip via build_looped() (see groovegen.py::build_looped). That is
    deliberate. An earlier engine (continuous.py::build_varied_drums) instead
    re-synthesized every bar with fresh per-bar stochastic jitter on density/
    syncopation, and a user A/B test REJECTED that engine's feel in favor of
    this one's steady, bit-identical tiling — the per-bar randomization read
    as incoherent, not more 'alive'. So: variety belongs only as sparse,
    scheduled, deterministic musical events layered on top of the same tiled
    core (fills every 4/8 bars, phrase-level velocity arcs, etc. — see Track 2
    in HYBRID_IMPROVEMENT_ROADMAP.md), never as global per-bar re-randomization
    of density/syncopation/swing. render_aligned_drum_bar() (below) preserves
    this contract for the per-bar/closed-loop path: the *commanded* density
    can change bar-to-bar (that's the whole point of the controller), but for
    a FIXED density + fixed bar_idx the output is byte-for-byte deterministic
    (seeded from (seed, bar_idx), not from an RNG that advances across calls).
    """
    sr = bed_info["sr"]
    tempo_bpm = bed_info["tempo_bpm"]
    bed_dur = bed_info["duration_s"]
    downbeat_s = bed_info["downbeat_s"]
    sf2_path = sf2_path or gg.default_sf2()

    # How many bars of drums do we need? _build_bed_grid BACK-PROJECTS the grid
    # to the start of the audio (so beds whose only reliable downbeat is late --
    # e.g. a sparse neo-soul bed with downbeats at 8.5 s -- still get drums from
    # the top). We must therefore generate enough bars to cover the WHOLE bed
    # from t=0, not just from the (possibly late) detected downbeat. Using
    # bed_dur - downbeat_s here previously produced a single bar of drums that
    # only sounded in the last few seconds.
    sec_per_bar = (60.0 / tempo_bpm) * 4.0  # 4/4
    cover_s = float(bed_dur)
    n_bars = max(1, int(np.ceil(cover_s / sec_per_bar)) + 1)  # +1 bar of headroom

    # Build the drum pattern at the DETECTED tempo (conform), knobs intact.
    # CRITICAL: with_bed=False. In the stem-hybrid path the *neural* bed carries
    # all pitched/harmonic content, so the symbolic stem must be DRUMS ONLY.
    # Leaving the symbolic bed on (the default) layers a second bass+chords+
    # melody in a DIFFERENT key on top of the neural bed -> the harmony clash.
    params = gg.GrooveParams(
        tempo_bpm=float(tempo_bpm),
        bars=n_bars,
        target_seconds=cover_s if cover_s > 0 else sec_per_bar,
        seed=int(seed),
        event_density=int(event_density),
        swing_amount=float(swing_amount),
        syncopation_level=float(syncopation_level),
        microtiming_variance_ms=float(microtiming_variance_ms),
        drum_style=drum_style,
        with_bed=False,
    )
    pm = gg.PatternBuilder(params).build_looped()

    # ---- SYMBOLIC TIME-MAP (no audio warping) -------------------------------
    # We DO NOT render the drums at a fixed tempo and then stretch the finished
    # audio onto the bed (that is lossy: it adds resampling artifacts and, when
    # the detected grid runs past the rendered drum audio, dead-silent gaps).
    #
    # Instead we move every drum NOTE in the MIDI to its correct time on the
    # bed's real beat grid BEFORE rendering, then render exactly once. Each
    # onset is placed where the bed's pulse actually is, so the drums are 'born'
    # on-grid -- there is nothing to stretch and nothing can fall into silence.
    # The groove knobs are untouched: swing / syncopation / microtiming were
    # already baked into the note times as fractions of a beat, and a piecewise-
    # linear beat map preserves those intra-beat fractions exactly.
    # Shared warp math (Roadmap 4.1): build_time-map exactly once, from the
    # SAME helper the per-bar path (render_aligned_drum_bar) uses, so the two
    # entry points can never diverge in how drum-clock time is warped onto
    # the bed clock.
    map_time, sec_per_beat, bed_grid = _make_map_time(bed_info)

    if map_time is not None:
        # The bed has a hard duration. A note whose mapped START lands at or
        # past the end of the bed audio makes FluidSynth try to write samples
        # into a zero-length slice -> 'operands could not be broadcast together
        # with shapes (0,) (N,) (0,)'. So we (a) drop notes that start beyond
        # the bed, and (b) clamp every note END to sit safely inside the buffer.
        max_start = max(0.0, bed_dur - 0.05)      # last legal note onset
        max_end   = max(0.02, bed_dur - 0.01)     # never render past the buffer
        for inst in pm.instruments:
            kept = []
            for n in inst.notes:
                dur = n.end - n.start
                ns = map_time(n.start)
                if ns >= max_start or ns < 0:
                    continue                       # onset past (or before) the bed -> drop
                ne = ns + max(0.02, dur)
                if ne > max_end:
                    ne = max_end
                if ne <= ns:                       # degenerate after clamp -> drop
                    continue
                n.start = ns
                n.end = ne
                kept.append(n)
            inst.notes = kept

    # Render the (time-mapped) drum MIDI once -> already aligned to the bed.
    tmp = (out_wav or os.path.join(os.path.dirname(bed_info.get("_src", ".")) or ".",
                                   "_drums_tmp.wav"))
    gg.render_wav(pm, tmp, sf2_path=sf2_path, fs=sr, target_lufs=-16.0)
    d, _ = librosa.load(tmp, sr=sr, mono=True)

    # Fit to the bed length (pad with silence or trim) -- no resampling.
    target_len = int(round(bed_dur * sr))
    aligned = np.zeros(target_len, dtype=np.float32)
    nseg = min(len(d), target_len)
    aligned[:nseg] = d[:nseg]

    return dict(drums=aligned, sr=sr, n_bars=n_bars, tempo_bpm=tempo_bpm,
                params=params, drums_wav=tmp)


# --------------------------------------------------------------------------
# 2b. PER-BAR entry point (Roadmap 4.1) — the closed-loop fast-loop callable
# --------------------------------------------------------------------------
def render_aligned_drum_bar(
    bed_info: dict,
    bar_idx: int,
    *,
    drum_style: str,
    event_density: int = 10,
    syncopation_level: float = 0.3,
    swing_amount: float = 1.0,
    microtiming_variance_ms: float = 0.0,
    seed: int = 0,
    sf2_path: str | None = None,
) -> dict:
    """Render ONE bar of aligned drums at a live-commanded event_density.

    This is the fast-loop entry point the PD controller calls every ~2-2.5 s
    (one bar period): push in the current bar index + the current commanded
    event_density, get back exactly that bar's audio, aligned to the bed's
    real clock. It does NOT call analyze_bed — pass a bed_info produced by
    get_bed_info() (cached; Roadmap 4.2) so the slow madmom+HPSS analysis
    happens once per bed, not once per bar.

    DETERMINISTIC-TILE CONTRACT (Roadmap 2.5 — see the design note on
    render_aligned_drums above for the full rationale): the *commanded*
    event_density is allowed to change bar-to-bar — that's the point of the
    controller — but for a FIXED (seed, bar_idx, drum_style, knobs) the
    output bar is byte-for-byte reproducible. We seed the bar's PatternBuilder
    RNG from a deterministic combination of (seed, bar_idx) rather than
    letting a single RNG advance call-to-call, and we build the bar with
    GrooveParams(bars=1) (PatternBuilder.build_core(), NOT build_looped()) so
    there is no hidden repeat-count/tiling state carried between calls. This
    is the same 'no per-bar stochastic re-randomization of density/
    syncopation' guardrail as 2.5 — only the density VALUE is live; nothing
    about how a given density is realized is randomized per call.

    ALIGNMENT: reuses _make_map_time(bed_info) — the SAME closure
    render_aligned_drums() uses — so both entry points warp drum-clock time
    to bed-clock time identically. A note at local time t within this bar
    lives at GLOBAL drum-clock time `t + bar_idx * sec_per_bar` (i.e. as if it
    were bar `bar_idx` of one continuous multi-bar render), which is then run
    through map_time(). The bar's audio WINDOW on the bed clock is therefore
    [map_time(bar_idx*sec_per_bar), map_time((bar_idx+1)*sec_per_bar)] —
    reported back as t_start_s/t_end_s so the caller can schedule playback.

    BACKBEAT LOCK: drum_style's backbeat (snare, or the genre's designated
    back_voice, on steps 4 & 12 = beats 2 & 4) comes from
    PatternBuilder._build_core_genre / build_core, which places the backbeat
    independently of event_density (density only adds hat/ghost subdivisions,
    see _density_steps / _genre_hat_steps) — so the backbeat anchor is
    preserved automatically here exactly as in the batch path; see
    step_perbar_findings.md for the empirical verification.

    Returns dict(drums_bar, sr, bar_idx, tempo_bpm, t_start_s, t_end_s, params).
    drums_bar is a 1-D float32 array covering exactly the bed-clock window
    [t_start_s, t_end_s) at bed_info['sr'].
    """
    sr = bed_info["sr"]
    tempo_bpm = bed_info["tempo_bpm"]
    bed_dur = bed_info["duration_s"]
    sf2_path = sf2_path or gg.default_sf2()
    sec_per_beat = bed_info.get("sec_per_beat") or (60.0 / tempo_bpm)
    sec_per_bar = bed_info.get("sec_per_bar") or (sec_per_beat * 4.0)

    # ---- Deterministic per-bar seed: (seed, bar_idx) -> one fixed int ------
    # A fixed hash of (seed, bar_idx, drum_style) so the SAME bar_idx at the
    # SAME commanded density/knobs always reproduces the same bar, but
    # different bars (or a different base seed) don't collide. We do not
    # advance any shared RNG state across calls — each call is independent
    # and reproducible in isolation (required for the reconstruction test and
    # for a controller that may re-render/replay an arbitrary bar_idx).
    bar_seed = (int(seed) * 1_000_003 + int(bar_idx) * 97) % (2 ** 31 - 1)

    # ---- Build exactly ONE bar of drums at the live-commanded density ------
    # bars=1 + build_core() (NOT build_looped()) so no tiling/repeat state is
    # implied — this call renders one bar and only one bar, full stop.
    params = gg.GrooveParams(
        tempo_bpm=float(tempo_bpm),
        bars=1,
        target_seconds=sec_per_bar,
        seed=bar_seed,
        event_density=int(event_density),
        swing_amount=float(swing_amount),
        syncopation_level=float(syncopation_level),
        microtiming_variance_ms=float(microtiming_variance_ms),
        drum_style=drum_style,
        with_bed=False,
    )
    pm = gg.PatternBuilder(params).build_core()

    # ---- Shared warp: local bar time -> global drum-clock time -> bed time -
    map_time, _sec_per_beat, _bed_grid = _make_map_time(bed_info)
    bar_offset = float(bar_idx) * sec_per_bar

    if map_time is not None:
        max_start = max(0.0, bed_dur - 0.05)
        max_end = max(0.02, bed_dur - 0.01)
        for inst in pm.instruments:
            kept = []
            for n in inst.notes:
                dur = n.end - n.start
                ns = map_time(n.start + bar_offset)
                if ns >= max_start or ns < 0:
                    continue
                ne = ns + max(0.02, dur)
                if ne > max_end:
                    ne = max_end
                if ne <= ns:
                    continue
                n.start = ns
                n.end = ne
                kept.append(n)
            inst.notes = kept
        t_start_s = map_time(bar_offset)
        t_end_s = map_time(bar_offset + sec_per_bar)
    else:
        # No usable beat grid (degenerate bed_info) — fall back to the raw
        # fixed-tempo bar window; notes are left at their local bar times
        # shifted by bar_offset (still monotonic/aligned to each other, just
        # not warped to a detected bed pulse).
        for inst in pm.instruments:
            for n in inst.notes:
                n.start += bar_offset
                n.end += bar_offset
        t_start_s = bar_offset
        t_end_s = bar_offset + sec_per_bar

    if t_end_s <= t_start_s:
        t_end_s = t_start_s + 1e-3

    # ---- Render just this bar's audio slice ---------------------------------
    # pm's notes currently sit at their bed-clock times (post map_time, i.e.
    # around [t_start_s, t_end_s]). FluidSynth/pretty_midi always renders
    # starting from the object's own t=0, so we re-zero every note by
    # t_start_s: sample 0 of the rendered buffer then corresponds exactly to
    # bed-clock time t_start_s, and the buffer spans bar_audio_dur seconds
    # (= t_end_s - t_start_s), i.e. this bar's own window on the bed clock.
    bar_audio_dur = max(1e-3, t_end_s - t_start_s)
    for inst in pm.instruments:
        for n in inst.notes:
            n.start = max(0.0, n.start - t_start_s)
            n.end = max(n.start + 0.02, n.end - t_start_s)

    target_len = int(round(bar_audio_dur * sr))
    drums_bar = np.zeros(max(target_len, 1), dtype=np.float32)

    # A bar can legitimately end up with NO notes after the bed-boundary drop
    # (e.g. a tail bar whose mapped onset lands past bed_dur -- the same
    # 'drop notes past the bed' rule render_aligned_drums applies, ~line 737).
    # In the batch path this never surfaces as an empty render because ALL
    # bars share one PrettyMIDI object with at least some earlier notes; a
    # per-bar call can isolate exactly the empty tail bar, so we return
    # silence for that bar instead of letting FluidSynth raise on an empty
    # buffer (gg.render_wav raises RuntimeError for empty audio).
    has_notes = any(len(inst.notes) for inst in pm.instruments)
    if has_notes:
        out_dir = os.path.join(os.path.dirname(os.path.abspath(bed_info.get("_src", "."))) or ".",
                               ".perbar_tmp")
        os.makedirs(out_dir, exist_ok=True)
        tmp = os.path.join(out_dir, f"_bar{bar_idx:05d}_{bar_seed}.wav")
        gg.render_wav(pm, tmp, sf2_path=sf2_path, fs=sr, target_lufs=-16.0)
        d, _ = librosa.load(tmp, sr=sr, mono=True)
        nseg = min(len(d), len(drums_bar))
        drums_bar[:nseg] = d[:nseg]

    return dict(drums_bar=drums_bar, sr=sr, bar_idx=int(bar_idx),
                tempo_bpm=tempo_bpm, t_start_s=float(t_start_s),
                t_end_s=float(t_end_s), params=params)


def _simple_align(d: np.ndarray, sr: int, downbeat_s: float,
                  target_len: int) -> np.ndarray:
    """Fallback: pad front by downbeat, trim/pad tail (no warp)."""
    pad_front = int(round(downbeat_s * sr))
    aligned = np.zeros(target_len, dtype=np.float32)
    seg = d[: max(0, target_len - pad_front)]
    aligned[pad_front: pad_front + len(seg)] = seg
    return aligned


# --------------------------------------------------------------------------
# 4. Mix bed + drums
# --------------------------------------------------------------------------
def _onset_env_lowband(drums: np.ndarray, sr: int,
                       lo: float = 40.0, hi: float = 120.0) -> np.ndarray:
    """Sample-rate envelope of the drums' LOW band (kick energy), 0..1.

    Used to build a sidechain duck: where the kick is loud, we briefly pull the
    bed's low end down so kick and bass don't stack into mud.
    """
    # crude band-limit via FFT mask, then Hilbert-ish envelope via abs + smooth
    try:
        from scipy.signal import butter, sosfiltfilt
        sos = butter(4, [lo, hi], btype="band", fs=sr, output="sos")
        band = sosfiltfilt(sos, drums)
    except Exception:
        band = drums
    env = np.abs(band).astype(np.float32)
    # smooth with a ~15 ms moving average (attack/release feel)
    win = max(1, int(0.015 * sr))
    kernel = np.ones(win, dtype=np.float32) / win
    env = np.convolve(env, kernel, mode="same")
    m = float(env.max()) + 1e-9
    return env / m


def mix_stems(bed_info: dict, drum_info: dict, out_wav: str,
              bed_gain_db: float = -2.0, drum_gain_db: float = -4.5,
              peak_ceiling_db: float = -1.0,
              bed_hpf_hz: float = 45.0,
              sidechain_depth_db: float = 5.0,
              clarity: bool = True) -> dict:
    """Sum bed + aligned drums into one file with a small HYBRID MIX BUS.

    Beyond a flat sum, this does three cheap, musical things that remove the
    'melody vs. drums clash' in the stem-hybrid path (each measured on real
    beds, see commit notes):

      1. BED HIGH-PASS (bed_hpf_hz): roll off the bed below ~45 Hz so the
         symbolic KICK owns the sub-bass instead of fighting the bed's low
         rumble (the two were stacking into mud at 40-90 Hz).
      2. KICK SIDECHAIN DUCK (sidechain_depth_db): wherever the kick is loud,
         briefly dip the bed's LOW band (40-250 Hz). Kick and bass then 'take
         turns' in the low end rather than colliding -- the classic pop/EDM
         trick, done gently. 0 dB disables it.
      3. DRUM LEVEL (drum_gain_db default -4.5): the old default summed drums at
         full level, which masked the melody's midrange. Pulling the kit back a
         few dB lets the bed's tune sit on top while the groove still drives.

    All three are parameters so you can dial or disable them; set clarity=False
    to fall back to the plain flat sum (old behavior).
    """
    sr = bed_info["sr"]
    bed = bed_info["y"].astype(np.float32).copy()
    drums = drum_info["drums"].astype(np.float32).copy()
    n = min(len(bed), len(drums))
    bed, drums = bed[:n], drums[:n]

    if clarity:
        # (1) high-pass the bed so the kick owns the sub
        if bed_hpf_hz and bed_hpf_hz > 20:
            try:
                from scipy.signal import butter, sosfiltfilt
                sos = butter(2, bed_hpf_hz, btype="high", fs=sr, output="sos")
                bed = sosfiltfilt(sos, bed).astype(np.float32)
            except Exception:
                pass
        # (2) sidechain-duck the bed's low band under the kick
        if sidechain_depth_db and sidechain_depth_db > 0:
            duck_env = _onset_env_lowband(drums, sr, 40.0, 120.0)  # 0..1
            depth = 1.0 - 10 ** (-abs(sidechain_depth_db) / 20.0)   # max attenuation fraction
            try:
                from scipy.signal import butter, sosfiltfilt
                sos = butter(2, 250.0, btype="low", fs=sr, output="sos")
                bed_low = sosfiltfilt(sos, bed).astype(np.float32)
                bed_high = bed - bed_low
                gain = (1.0 - depth * duck_env).astype(np.float32)
                bed = bed_high + bed_low * gain
            except Exception:
                gain = (1.0 - depth * duck_env).astype(np.float32)
                bed = bed * gain

    bed *= 10 ** (bed_gain_db / 20.0)
    drums *= 10 ** (drum_gain_db / 20.0)
    mix = bed + drums

    # peak-normalize to the ceiling to avoid clipping
    peak = np.max(np.abs(mix)) + 1e-9
    ceiling = 10 ** (peak_ceiling_db / 20.0)
    if peak > ceiling:
        mix *= ceiling / peak

    sf.write(out_wav, mix, sr)
    return dict(out_wav=out_wav, sr=sr, duration_s=n / sr,
                peak=float(np.max(np.abs(mix))),
                clarity=clarity, bed_hpf_hz=bed_hpf_hz,
                sidechain_depth_db=sidechain_depth_db,
                drum_gain_db=drum_gain_db)


# --------------------------------------------------------------------------
# Convenience: full pipeline in one call
# --------------------------------------------------------------------------
def hybrid_render(bed_wav: str, drum_style: str, out_wav: str,
                  expected_tempo: float | None = None,
                  lock_tempo: float | None = None,
                  tempo_min: float | None = None,
                  tempo_max: float | None = None,
                  mix_kwargs: dict | None = None,
                  suppress_bed_drums: bool = False,
                  suppress_margin: float = 3.0,
                  protect_melody: bool = True,
                  protect_hz: float = 2000.0,
                  protect_blend: float = 1.0,
                  **knob_kwargs) -> dict:
    """End-to-end: bed audio + symbolic drums -> one aligned, mixed file.

    knob_kwargs are forwarded to render_aligned_drums (event_density,
    syncopation_level, swing_amount, microtiming_variance_ms, seed, sf2_path).

    TEMPO OCTAVE GUARD
    ------------------
    madmom's tempo is octave-ambiguous: a 63 BPM calm bed is easily reported as
    126 BPM (double-time), which would make the drums play twice as fast as the
    bed. The default detection band is 70-180 BPM, which is WRONG for slow calm
    beds (it would force 63 -> 126). Pass `expected_tempo` (e.g. the preset's
    tempo_hint) and we centre the octave-correction band on it (+/- ~40%) so the
    true tempo is kept instead of doubled/halved. You can also set tempo_min/
    tempo_max explicitly to override.
    """
    # NOTE: we deliberately do NOT narrow the octave-correction band from
    # expected_tempo. Narrowing the band can fold the raw estimate to the wrong
    # octave BEFORE the grid-level octave snap runs, and the two corrections then
    # fight. The expected_tempo prior is applied cleanly inside analyze_bed via
    # _octave_snap_grid, which compares the detected inter-beat interval to the
    # expected one and densifies/thins the grid to the right octave. The band
    # (tempo_min/tempo_max) is left at its robust default unless the caller
    # overrides it explicitly.
    kw = {}
    if tempo_min is not None:
        kw["tempo_min"] = float(tempo_min)
    if tempo_max is not None:
        kw["tempo_max"] = float(tempo_max)
    if expected_tempo is not None:
        kw["expected_tempo"] = float(expected_tempo)
    if lock_tempo is not None:
        kw["lock_tempo"] = float(lock_tempo)
    kw["suppress_bed_drums"] = bool(suppress_bed_drums)
    kw["suppress_margin"] = float(suppress_margin)
    kw["protect_melody"] = bool(protect_melody)
    kw["protect_hz"] = float(protect_hz)
    kw["protect_blend"] = float(protect_blend)
    bed_info = analyze_bed(bed_wav, **kw)
    bed_info["_src"] = bed_wav
    drum_info = render_aligned_drums(bed_info, drum_style, **knob_kwargs)
    # mix_kwargs lets the caller tune the hybrid mix bus (bed_hpf_hz,
    # sidechain_depth_db, drum_gain_db, bed_gain_db, clarity). Defaults are the
    # clarity-on settings that resolve the melody-vs-drums clash.
    mix_info = mix_stems(bed_info, drum_info, out_wav, **(mix_kwargs or {}))
    return dict(
        out_wav=out_wav,
        detected_tempo_bpm=round(bed_info["tempo_bpm"], 1),
        downbeat_s=round(bed_info["downbeat_s"], 3),
        n_bars=drum_info["n_bars"],
        duration_s=round(mix_info["duration_s"], 2),
        knobs=knob_kwargs,
        bed_drums_suppressed=bool(suppress_bed_drums),
        mix=dict(clarity=mix_info.get("clarity"),
                 bed_hpf_hz=mix_info.get("bed_hpf_hz"),
                 sidechain_depth_db=mix_info.get("sidechain_depth_db"),
                 drum_gain_db=mix_info.get("drum_gain_db")),
    )
